INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3949336',2061,83,'P1','Contabilidade Geral - Balanço Patrimonial','IBFC - TNS (SEC BA)/SEC BA/Ciências Contábeis/2026','Caderno Contabilidade Geral Parte 2','A empresa KLM Ltda apresentou, no último exercício, saldos contábeis registrados no quadro a seguir. Contas contábeis Valores R$ Bancos 27.000,00 Capital 200.000,00 Matéria prima 12.000,00 Direitos autorais 3.000,00 Fornecedores 40.000,00 Produtos acabados 25.000,00 Tributos a Recolher 30.000,00 Veículos 30.000,00 Máquinas / Equipamentos. 50.000,00 Custo dos produtos vendidos 25.000,00 Ações empresas controladas 25.000,00 Aplicações financeiras 15.000,00 Receitas de Vendas 70.000,00 Clientes 28.000,00 Despesas administrativas 13.000,00 Produtos em elaboração 13.000,00 Receitas financeiras 3.000,00 Marcas e patentes 7.000,00 Com base apenas nas informações apresentadas acima, analise as afirmativas abaixo e dê valores Verdadeiro (V) ou Falso (F). ( ) O valor do ativo intangível é R$ 7.000,00. ( ) O valor do ativo não circulante é R$ 112.000,00. ( ) O valor do patrimônio líquido da empresa é R$ 235.000,00. ( ) O valor do estoque é R$ 27.000,00. ( ) O valor do ativo circulante é R$ 120.000,00. Assinale a alternativa que apresenta a sequência correta de cima para baixo.','[["A","V – V – V – V – V"],["B","V – V – F – V – F"],["C","F – F – V – V – F"],["D","F – F – V – F – V"],["E","F – F – F – F – V"]]'::jsonb,'D',2026,270,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Balanço Patrimonial.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — F – F – V – F – V","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Balanço Patrimonial"}'::jsonb,'A empresa KLM Ltda apresentou, no último exercício, saldos contábeis registrados no quadro a seguir. Contas contábeis Valores R$ Bancos 27.000,00 Capital 200.000,00 Matéria prima 12.000,00 Direitos autorais 3.000,00 Fornecedores 40.000,00 Produtos acabados 25.000,00 Tributos a...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
