INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3962588',2065,83,'P1','Contabilidade Geral - Balanço Patrimonial','IBAM - AFTM (Pref São Vicente)/Pref São Vicente/Processo Tributário/2026','Caderno Contabilidade Geral Parte 2','Assinale a alternativa incorreta.','[["A","No ativo, as contas são dispostas em ordem decrescente de grau de liquidez, sendo agrupadas em ativo circulante e ativo não circulante, este último composto por ativo realizável a longo prazo, investimentos, imobilizado e intangível."],["B","No ativo imobilizado, são classificados os direitos que tenham por objeto bens corpóreos destinados à manutenção das atividades da companhia, inclusive os decorrentes de operações que transfiram à companhia os benefícios, riscos e controle desses bens"],["C","As obrigações da companhia, incluindo financiamentos para aquisição de direitos do ativo não circulante, serão classificadas no passivo circulante quando se vencerem no exercício seguinte, e no passivo não circulante se tiverem vencimento em prazo maior, sem qualquer exceção relacionada ao ciclo operacional."],["D","O ativo circulante inclui as disponibilidades, os direitos realizáveis no curso do exercício social subsequente e as aplicações de recursos em despesas do exercício seguinte, enquanto o ativo realizável a longo prazo abrange os direitos realizáveis após o término do exercício seguinte."]]'::jsonb,'C',2026,274,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Balanço Patrimonial.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — As obrigações da companhia, incluindo financiamentos para aquisição de direitos do ativo não circulante, serão classificadas no passivo circulante quando se vencerem no exercício seguinte, e no passivo não circulante se tiverem vencimento em prazo maior, sem qualquer exceção relacionada ao ciclo operacional.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Balanço Patrimonial"}'::jsonb,'Assinale a alternativa incorreta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
