INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4076222',2086,69,'P2','Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)','FGV - Ana (TJ SC)/TJ SC/Contábil-Econômico/2026','Caderno Contabilidade Geral Parte 2','Em 01/11/2025, uma entidade iniciou o desenvolvimento de um software, para uso interno em suas atividades. A conclusão do projeto estava prevista para abril de 2026, com início de utilização em maio do mesmo ano. Durante o exercício de 2025, a entidade realizou os seguintes desembolsos relacionados ao desenvolvimento do software: R$ 5.000 com atividades destinadas à obtenção de novos conhecimentos; R$ 10.000 com a busca de alternativas para sistemas; R$ 12.000 com a avaliação e a seleção final de alternativas possíveis para o processo. Na Demonstração dos Fluxos de Caixa anual, em 31/12/2025, o consumo de caixa classificado nas Atividades Operacionais corresponde a','[["A","zero."],["B","R$ 5.000."],["C","R$ 15.000."],["D","R$ 17.000."],["E","R$ 27.000."]]'::jsonb,'E',2026,359,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — R$ 27.000.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)"}'::jsonb,'Em 01/11/2025, uma entidade iniciou o desenvolvimento de um software, para uso interno em suas atividades. A conclusão do projeto estava prevista para abril de 2026, com início de utilização em maio do mesmo ano. Durante o exercício de 2025, a entidade realizou os seguintes de...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4014406',2087,69,'P2','Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)','Instituto AOCP - Tecno (IF CE)/IF CE/Gestão Financeira/2026','Caderno Contabilidade Geral Parte 2','Um servidor de um instituto federal extraiu as seguintes informações da Demonstração do Fluxo de Caixa (DFC): Valor Descrição (em R$) Recebimentos de caixa decorrentes de 1.500 impostos Pagamentos em caixa por arrendatário 1.500 Recebimentos de caixa decorrentes de 3.000 royalties Caixa recebido proveniente da emissão de 3.500 debêntures Recebimentos de caixa de sinistros 4.500 Recebimentos de caixa provenientes da 1.500 venda de instrumentos patrimoniais Pagamentos em caixa a fornecedores de 2.000 mercadorias e serviços Recebimentos de caixa resultantes da 3.000 venda de ativo imobilizado Com base nas informações fornecidas, assinale a alternativa correta.','[["A","A atividade operacional gerou caixa de R$ 4.500."],["B","A atividade de investimento consumiu caixa de R$ 1.500."],["C","A atividade de financiamento gerou caixa de R$ 6.500."],["D","A atividade operacional consumiu caixa de R$ 2.500."],["E","A atividade de financiamento gerou caixa de R$ 2.000."]]'::jsonb,'E',2026,360,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é E."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"E — A atividade de financiamento gerou caixa de R$ 2.000.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)"}'::jsonb,'Um servidor de um instituto federal extraiu as seguintes informações da Demonstração do Fluxo de Caixa (DFC): Valor Descrição (em R$) Recebimentos de caixa decorrentes de 1.500 impostos Pagamentos em caixa por arrendatário 1.500 Recebimentos de caixa decorrentes de 3.000 royal...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4061938',2088,69,'P2','Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)','Instituto Verbena - ACI (Pref Sen Can)/Pref Sen Can/Ciências Contábeis/2026','Caderno Contabilidade Geral Parte 2','Uma empresa comercial apresentou os seguintes fluxos de caixa no período: Dividendos pagos aos acionistas: R$ 12.000,00 Dividendos recebidos: R$ 10.000,00 Juros pagos: R$ 18.000,00 Juros recebidos: R$ 6.000,00 Juros sobre capital próprio (JCP) recebidos: R$ 4.000,00 A entidade opta pela classificação alternativa, justificando essa escolha em suas notas explicativas. Com base apenas nas informações apresentadas e no CPC 03, qual é o valor dos fluxos de caixa operacional, de investimento e de financiamento, respectivamente?','[["A","16.000,00; -16.000,00 e 18.000,00."],["B","18.000,00; -16.000,00 e 16.000,00."],["C","-16.000,00; 16.000,00 e -18.000,00."],["D","-18.000,00; 16.000,00 e -16.000,00."]]'::jsonb,'C',2026,361,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — -16.000,00; 16.000,00 e -18.000,00.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)"}'::jsonb,'Uma empresa comercial apresentou os seguintes fluxos de caixa no período: Dividendos pagos aos acionistas: R$ 12.000,00 Dividendos recebidos: R$ 10.000,00 Juros pagos: R$ 18.000,00 Juros recebidos: R$ 6.000,00 Juros sobre capital próprio (JCP) recebidos: R$ 4.000,00 A entidade...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4066841',2089,69,'P2','Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)','FUNDATEC - Teso (Pref Bento Gonçalves)/Pref Bento Gonçalves/2026','Caderno Contabilidade Geral Parte 2','Com base nos fundamentos da administração financeira e na demonstração dos fluxos de caixa, analise as assertivas a seguir: I. O fluxo de caixa tem por finalidade evidenciar as entradas e saídas de recursos financeiros em determinado período. II. A elaboração do fluxo de caixa permite à empresa planejar a liquidez e antecipar necessidades de capital de giro. III. O fluxo de caixa deve considerar apenas os recebimentos e pagamentos já realizados, não incluindo valores previstos. Quais estão corretas?','[["A","Apenas I."],["B","Apenas I e II."],["C","Apenas I e III."],["D","Apenas II e III."],["E","I, II e III."]]'::jsonb,'B',2026,362,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — Apenas I e II.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Demonstração de Fluxo de Caixa (DFC - CPC 03, Lei 6.404, art. 188, I)"}'::jsonb,'Com base nos fundamentos da administração financeira e na demonstração dos fluxos de caixa, analise as assertivas a seguir: I. O fluxo de caixa tem por finalidade evidenciar as entradas e saídas de recursos financeiros em determinado período. II. A elaboração do fluxo de caixa...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4122814',2090,69,'P2','Contabilidade Geral - Demonstração do Valor Adicionado (DVA - CPC 09, Lei 6.404, art. 188, II)','FCC - AFFE (SEFAZ CE)/SEFAZ CE/Gestão Fazendária/2026','Caderno Contabilidade Geral Parte 2','A Demonstração do Resultado do ano de 2025 da empresa Produtos Sustentáveis S.A. é apresentada a seguir, com os valores expressos em reais: Receita Bruta de Vendas............................................................................ 4.900.000 (-) Impostos sobre vendas........................................................................ (1.200.000) (=) Receita Líquida..................................................................................... 3.700.000 (-) Custo dos Produtos Vendidos.............................................................. (2.350.000) (=) Lucro Bruto............................................................................................. 1.350.000 (-) Despesas operacionais........................................................................................... Perdas estimadas com crédito de liquidação duvidosa......................... (25.000) Despesa de depreciação..................................................................... (250.000) Despesa com pessoal......................................................................... (150.000) (+) Resultado de Equivalência Patrimonial....................................................... 35.000 (+) Receitas financeiras...................................................................................... 65.000 (=) Lucro antes do IR e CSLL.......................................................................... 1.025.000 (-) IR e CSLL..................................................................................................... (275.000) (=) Lucro Líquido............................................................................................. 750.000 Se o valor dos tributos recuperáveis, referentes aos produtos que foram vendidos no ano de 2025, totalizava R$ 225.000, o Valor Adicionado Total a Distribuir gerado pela empresa, no ano de 2025, foi, em reais,','[["A","2.150.000."],["B","2.075.000."],["C","2.050.000."],["D","2.325.000."],["E","2.140.000."]]'::jsonb,'A',2026,371,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Demonstração do Valor Adicionado (DVA - CPC 09, Lei 6.404, art. 188, II).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — 2.150.000.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Demonstração do Valor Adicionado (DVA - CPC 09, Lei 6.404, art. 188, II)"}'::jsonb,'A Demonstração do Resultado do ano de 2025 da empresa Produtos Sustentáveis S.A. é apresentada a seguir, com os valores expressos em reais: Receita Bruta de Vendas............................................................................ 4.900.000 (-) Impostos sobre vendas.....') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4013919',2091,83,'P1','Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)','Instituto AOCP - Cont (IF CE)/IF CE/2026','Caderno Contabilidade Geral Parte 3','O IFCE possui unidades gestoras (campi) inscritas no CNPJ na condição de filiais. No processo de implementação da DCTFWeb, a equipe técnica avaliou a responsabilidade pela prestação das informações e os requisitos de validade jurídica do documento. De acordo com as normas da Secretaria da Receita Federal do Brasil e do sistema Sped, assinale a alternativa correta.','[["A","A DCTFWeb deve ser apresentada de forma centralizada pelo estabelecimento matriz, consolidando as informações de todas as unidades gestoras (filiais)."],["B","As unidades gestoras inscritas como filiais possuem autonomia para apresentar DCTFWeb individualizada, sendo a entrega obrigatoriamente validada por certificado digital."],["C","A declaração é segmentada por campus, mas a administração pública direta goza de prerrogativa que dispensa a assinatura digital em qualquer circunstância."],["D","O envio deve ser realizado por cada filial separadamente, sendo permitida a assinatura exclusivamente via conta gov.br (nível ouro), independentemente do volume de movimentação."],["E","A responsabilidade pela entrega é exclusiva de cada unidade descentralizada, que deve encaminhar os dados por correio eletrônico à Receita Federal para a consolidação da guia."]]'::jsonb,'A',2026,402,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — A DCTFWeb deve ser apresentada de forma centralizada pelo estabelecimento matriz, consolidando as informações de todas as unidades gestoras (filiais).","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)"}'::jsonb,'O IFCE possui unidades gestoras (campi) inscritas no CNPJ na condição de filiais. No processo de implementação da DCTFWeb, a equipe técnica avaliou a responsabilidade pela prestação das informações e os requisitos de validade jurídica do documento. De acordo com as normas da S...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4117596',2092,83,'P1','Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)','FUNDATEC - AFRM (Caxias do Sul)/Pref Caxias do Sul/2026','Caderno Contabilidade Geral Parte 3','Nos termos do artigo 6º do Decreto Federal nº 6.022/2007, compete à Secretaria da Receita Federal adotar as medidas necessárias para viabilizar a implantação e o funcionamento do Sistema Público de Escrituração Digital (Sped), coordenar as atividades relacionadas ao sistema, compatibilizar as necessidades de seus usuários e','[["A","estabelecer a política de segurança e de acesso às informações armazenadas eletronicamente."],["B","definir as normas gerais para consolidação das contas públicas e para a padronização dos registros contábeis aplicáveis aos entes da Federação."],["C","disciplinar a divulgação das demonstrações financeiras das companhias abertas e regulamentar o acesso às informações prestadas ao mercado de capitais."],["D","estabelecer os procedimentos de supervisão prudencial das instituições financeiras e disciplinar o acesso aos sistemas de informações bancárias nacionais."]]'::jsonb,'A',2026,403,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é A."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"A — estabelecer a política de segurança e de acesso às informações armazenadas eletronicamente.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)"}'::jsonb,'Nos termos do artigo 6º do Decreto Federal nº 6.022/2007, compete à Secretaria da Receita Federal adotar as medidas necessárias para viabilizar a implantação e o funcionamento do Sistema Público de Escrituração Digital (Sped), coordenar as atividades relacionadas ao sistema, c...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3983639',2093,83,'P1','Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)','QUADRIX - Ana (CREFITO 17)/CREFITO 17/Contábil/2026','Caderno Contabilidade Geral Parte 3','Em março de 2025, o CREFITO‑17 realizou pagamentos a prestadores de serviços pessoas jurídicas e pessoas físicas, efetuou o recolhimento de encargos sobre a folha de pagamento e verificou as suas obrigações acessórias perante a Receita Federal do Brasil. A equipe fiscal precisou, assim, avaliar as retenções incidentes e os prazos das declarações. Com base nessa situação hipotética e na legislação tributária vigente, julgue o item a seguir. A EFD‑Reinf é uma escrituração fiscal digital integrante do SPED, sendo utilizada para declarar retenções na fonte e outras informações fiscais e previdenciárias não relacionadas ao trabalho. Dessa forma, por ser um sistema autônomo e independente, as informações nela prestadas não guardam relação com a geração da DCTFWeb, que utiliza exclusivamente os dados declarados no e Social.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2026,404,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)"}'::jsonb,'Em março de 2025, o CREFITO‑17 realizou pagamentos a prestadores de serviços pessoas jurídicas e pessoas físicas, efetuou o recolhimento de encargos sobre a folha de pagamento e verificou as suas obrigações acessórias perante a Receita Federal do Brasil. A equipe fiscal precis...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3983641',2094,83,'P1','Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)','QUADRIX - Ana (CREFITO 17)/CREFITO 17/Contábil/2026','Caderno Contabilidade Geral Parte 3','Em março de 2025, o CREFITO‑17 realizou pagamentos a prestadores de serviços pessoas jurídicas e pessoas físicas, efetuou o recolhimento de encargos sobre a folha de pagamento e verificou as suas obrigações acessórias perante a Receita Federal do Brasil. A equipe fiscal precisou, assim, avaliar as retenções incidentes e os prazos das declarações. Com base nessa situação hipotética e na legislação tributária vigente, julgue o item a seguir. A DCTFWeb deve ser transmitida até o último dia útil do mês seguinte ao da ocorrência dos fatos geradores, sendo elaborada com base nas informações prestadas no eSocial, na EFD‑Reinf e em sistemas e módulos complementares da Receita Federal, como o MIT e o SERO, que permitem a inclusão ou apuração de débitos tributários a serem consolidados na declaração.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Certo',2026,405,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Certo."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Certo — Certo","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)"}'::jsonb,'Em março de 2025, o CREFITO‑17 realizou pagamentos a prestadores de serviços pessoas jurídicas e pessoas físicas, efetuou o recolhimento de encargos sobre a folha de pagamento e verificou as suas obrigações acessórias perante a Receita Federal do Brasil. A equipe fiscal precis...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4007836',2095,83,'P1','Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)','Ibest - Cont (CRBM 5)/CRBM 5/2026','Caderno Contabilidade Geral Parte 3','A respeito do Sistema Público de Escrituração Digital (Sped), é correto afirmar que','[["A","o Sped dispensa as pessoas jurídicas, de manter sob sua guarda e responsabilidade os livros e documentos comerciais e fiscais."],["B","o acesso às informações do Sped será compartilhado com seus usuários, sem prejuízo da observância à legislação referente aos sigilos comercial, fiscal e bancário."],["C","cabe à administração tributária de cada ente compatibilizar as necessidades dos usuários do Sped."],["D","o Sped se aplica exclusivamente à escrituração fiscal dos contribuintes."],["E","as administrações tributárias dos Municípios celebrarão convênios com as respectivas administrações tributárias estaduais."]]'::jsonb,'B',2026,406,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED).","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — o acesso às informações do Sped será compartilhado com seus usuários, sem prejuízo da observância à legislação referente aos sigilos comercial, fiscal e bancário.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Decreto nº 6.022/2007 - Sistema Público de Escrituração Digital (SPED)"}'::jsonb,'A respeito do Sistema Público de Escrituração Digital (Sped), é correto afirmar que') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4013918',2096,83,'P1','Contabilidade Geral - Conceitos de SPED e seus Módulos','Instituto AOCP - Cont (IF CE)/IF CE/2026','Caderno Contabilidade Geral Parte 3','Uma unidade gestora do IFCE finalizou o lançamento dos eventos periódicos no eSocial e na EFD-Reinf. Ao acessar o portal da DCTFWeb, o operador observou que a declaração constava com o status “Em Andamento”. De acordo com o fluxo operacional estabelecido pela Receita Federal para a constituição do crédito tributário e arrecadação, para a conclusão do processo, deve-se','[["A","realizar a transmissão da DCTFWeb e, em ato contínuo, proceder com o envio dos eventos de fechamento das escriturações no eSocial."],["B","finalizar o envio dos eventos de fechamento (S- 1299 no eSocial e R-4099 na EFD-Reinf), acessar a declaração consolidada, transmitir e emitir o DARF Numerado."],["C","efetuar a emissão e o pagamento do DARF de forma antecipada, postergando a transmissão da declaração apenas para casos de fiscalização ativa."],["D","consolidar a transmissão apenas no ambiente do eSocial, visto que a DCTFWeb é alimentada automaticamente e dispensa a ação de transmissão manual para gerar a guia."],["E","aguardar o prazo de vencimento do tributo para processar a transmissão, uma vez que a DCTFWeb só adquire validade jurídica após a confirmação bancária do pagamento."]]'::jsonb,'B',2026,407,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceitos de SPED e seus Módulos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — finalizar o envio dos eventos de fechamento (S- 1299 no eSocial e R-4099 na EFD-Reinf), acessar a declaração consolidada, transmitir e emitir o DARF Numerado.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceitos de SPED e seus Módulos"}'::jsonb,'Uma unidade gestora do IFCE finalizou o lançamento dos eventos periódicos no eSocial e na EFD-Reinf. Ao acessar o portal da DCTFWeb, o operador observou que a declaração constava com o status “Em Andamento”. De acordo com o fluxo operacional estabelecido pela Receita Federal p...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3976736',2097,83,'P1','Contabilidade Geral - Conceitos de SPED e seus Módulos','QUADRIX - Cont (CRBM 6)/CRBM 6/2026','Caderno Contabilidade Geral Parte 3','O contador responsável pela área fiscal deverá observar corretamente as regras de retenção tributária e o cumprimento das obrigações acessórias. A partir dessa informação, julgue o item seguinte. A escrituração contábil fiscal (ECF) tem por finalidade registrar exclusivamente as informações contábeis da empresa, não contemplando os dados relacionados à apuração do imposto de renda ou da contribuição social.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2026,408,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceitos de SPED e seus Módulos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceitos de SPED e seus Módulos"}'::jsonb,'O contador responsável pela área fiscal deverá observar corretamente as regras de retenção tributária e o cumprimento das obrigações acessórias. A partir dessa informação, julgue o item seguinte. A escrituração contábil fiscal (ECF) tem por finalidade registrar exclusivamente ...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3632493',2098,83,'P1','Contabilidade Geral - Conceitos de SPED e seus Módulos','QUADRIX - Cont (CRM ES)/CRM ES/2025','Caderno Contabilidade Geral Parte 3','O Sistema Público de Escrituração Digital (SPED) é um projeto do governo brasileiro que moderniza, padroniza e integra o envio das informações fiscais, contábeis e previdenciárias das empresas aos órgãos fiscalizadores e, entre as suas principais características, destacam‑se • a substituição de livros em papel por arquivos digitais; • a padronização e a integração de dados; e • a redução da burocracia e o combate à sonegação. Considerando essas informações e os conhecimentos em relação aos módulos que fazem parte do SPED, assinale a opção, que apresenta corretamente um módulo do SPED.','[["A","DCTFWeb – declaração de débitos e créditos tributários federais web"],["B","DIRF – declaração do imposto sobre a renda retido na fonte"],["C","EFD‑ICMS/IPI – escrituração fiscal digital do ICMS e do IPI"],["D","RAIS – relação anual de informações sociais"],["E","GPS – Guia da Previdência Social"]]'::jsonb,'C',2025,409,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceitos de SPED e seus Módulos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — EFD‑ICMS/IPI – escrituração fiscal digital do ICMS e do IPI","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceitos de SPED e seus Módulos"}'::jsonb,'O Sistema Público de Escrituração Digital (SPED) é um projeto do governo brasileiro que moderniza, padroniza e integra o envio das informações fiscais, contábeis e previdenciárias das empresas aos órgãos fiscalizadores e, entre as suas principais características, destacam‑se •...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3623767',2099,83,'P1','Contabilidade Geral - Conceitos de SPED e seus Módulos','QUADRIX - Esp Ges (CRP 6 (SP))/CRP 6 (SP)/Contador/2025','Caderno Contabilidade Geral Parte 3','Acerca da legislação tributária e das obrigações fiscais, julgue o item a seguir. O Sistema Público de Escrituração Digital (SPED) é um instrumento que unifica as atividades de recepção, validação, armazenamento e autenticação de livros e documentos que integram a escrituração contábil e fiscal dos empresários e das pessoas jurídicas, exceto imunes ou isentas, mediante um fluxo único e computadorizado de informações.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2025,410,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceitos de SPED e seus Módulos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceitos de SPED e seus Módulos"}'::jsonb,'Acerca da legislação tributária e das obrigações fiscais, julgue o item a seguir. O Sistema Público de Escrituração Digital (SPED) é um instrumento que unifica as atividades de recepção, validação, armazenamento e autenticação de livros e documentos que integram a escrituração...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3681592',2100,83,'P1','Contabilidade Geral - Conceitos de SPED e seus Módulos','FUNDATEC - Ana Proj (BRDE)/BRDE/Contador/2025','Caderno Contabilidade Geral Parte 3','O Sistema Público de Escrituração Digital (SPED), instituído em 2007, integra as administrações tributária e fiscal nas esferas federal, estadual e municipal, substituindo diversas obrigações acessórias em papel por arquivos digitais. Entre suas principais vertentes, destacam-se a Escrituração Contábil Digital (ECD), a Escrituração Contábil Fiscal (ECF), a EFD-Reinf, a EFD-Contribuições e a e-Financeira, cada qual com suas finalidades específicas. Sobre o tema, analise as assertivas abaixo e assinale V, se verdadeiras, ou F, se falsas. ( ) A ECD substituiu a escrituração física do Livro Diário e do Livro Razão, sendo exigida de diversas pessoas jurídicas, inclusive aquelas imunes e isentas em determinadas situações. ( ) A ECF sucedeu a DIPJ, devendo ser transmitida por todas as pessoas jurídicas, inclusive as optantes pelo Simples Nacional. ( ) A EFD-Reinf complementa a EFD-Contribuições, abrangendo retenções previdenciárias, informações sobre serviços tomados ou prestados e dados da CPRB. ( ) A EFD-Contribuições trata da escrituração do ICMS e do IPI, sem incluir contribuições federais como PIS e Cofins. ( ) A e-Financeira é obrigação acessória destinada às instituições financeiras, seguradoras e administradoras de cartões, que devem reportar operações financeiras realizadas por pessoas físicas e jurídicas. A ordem correta de preenchimento dos parênteses, de cima para baixo, é:','[["A","F – V – F – V – F."],["B","F – F – F – V – V."],["C","V – F – V – F – V."],["D","V – F – F – V – F."],["E","F – V – V – F – V."]]'::jsonb,'C',2025,411,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceitos de SPED e seus Módulos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — V – F – V – F – V.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceitos de SPED e seus Módulos"}'::jsonb,'O Sistema Público de Escrituração Digital (SPED), instituído em 2007, integra as administrações tributária e fiscal nas esferas federal, estadual e municipal, substituindo diversas obrigações acessórias em papel por arquivos digitais. Entre suas principais vertentes, destacam-...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3681593',2101,83,'P1','Contabilidade Geral - Conceitos de SPED e seus Módulos','FUNDATEC - Ana Proj (BRDE)/BRDE/Contador/2025','Caderno Contabilidade Geral Parte 3','O SPED contempla diversos módulos, entre eles o que unifica a coleta de informações trabalhistas, previdenciárias, fiscais e tributárias, instituído pelo Decreto nº 8.373/2014. Em relação ao módulo descrito, assinale a alternativa correta.','[["A","Criou novas obrigações acessórias e substituiu integralmente a legislação trabalhista e previdenciária em vigor."],["B","Tem caráter facultativo para empregadores de pequeno porte e órgãos públicos."],["C","Centraliza e padroniza o envio de dados já exigidos pela legislação, sem alterar as normas materiais existentes."],["D","Dispensa, em todas as situações, o uso de certificado digital para transmissão de eventos."],["E","Ao recepcionar os eventos enviados, reconhece automaticamente a legalidade das informações prestadas."]]'::jsonb,'C',2025,412,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Conceitos de SPED e seus Módulos.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Centraliza e padroniza o envio de dados já exigidos pela legislação, sem alterar as normas materiais existentes.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Conceitos de SPED e seus Módulos"}'::jsonb,'O SPED contempla diversos módulos, entre eles o que unifica a coleta de informações trabalhistas, previdenciárias, fiscais e tributárias, instituído pelo Decreto nº 8.373/2014. Em relação ao módulo descrito, assinale a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3495933',2102,83,'P1','Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital','CEBRASPE (CESPE) - Cont (FUB)/FUB/2025','Caderno Contabilidade Geral Parte 3','Julgue o item a seguir, relativo ao plano de contas e aos procedimentos de escrituração. Pessoas jurídicas optantes do simples nacional bem como entidades imunes e isentas estão dispensadas da realização da escrituração contábil digital (ECD).','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2025,413,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital"}'::jsonb,'Julgue o item a seguir, relativo ao plano de contas e aos procedimentos de escrituração. Pessoas jurídicas optantes do simples nacional bem como entidades imunes e isentas estão dispensadas da realização da escrituração contábil digital (ECD).') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3754822',2103,83,'P1','Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital','VUNESP - ContJ (TJ SP)/TJ SP/2025','Caderno Contabilidade Geral Parte 3','Wesley está estudando a respeito da Escrituração Contábil Digital (ECD), conforme detalhamento contido na Instrução Normativa da RFB no 2.003/2021. A respeito dessa escrituração, é correto afirmar que','[["A","a assinatura da ECD para envio à Receita Federal do Brasil, a fim de garantir a autoria, a autenticidade, a integridade e a validade jurídica do documento digital, pode ser feita por qualquer meio de autenticação utilizado ordinariamente pela empresa para os seus negócios."],["B","compreende a versão digital dos livros contábeis Diário e seus auxiliares, quando houver; Razão e seus auxiliares, quando houver; e Balancetes Diários e Balanços, além de fichas de lançamento comprobatórias dos assentamentos neles transcritos."],["C","a obrigatoriedade da sua entrega se estende às empresas optantes pelo Simples Nacional, às instituições imunes nos termos da Constituição, bem como aos órgãos públicos, em relação aos tributos por eles retidos na fonte."],["D","a autenticação dos livros e documentos que integram a ECD das empresas mercantis será comprovada pelo recibo de entrega da ECD emitido pelo Sped ou por outra forma de autenticação, a critério das Juntas Comerciais."],["E","a ECD autenticada não pode ser substituída, ainda que contenha erros que não possam ser corrigidos por meio de lançamento contábil extemporâneo, por representar essa possibilidade uma fragilidade em relação à integridade da informação contábil."]]'::jsonb,'B',2025,414,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — compreende a versão digital dos livros contábeis Diário e seus auxiliares, quando houver; Razão e seus auxiliares, quando houver; e Balancetes Diários e Balanços, além de fichas de lançamento comprobatórias dos assentamentos neles transcritos.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital"}'::jsonb,'Wesley está estudando a respeito da Escrituração Contábil Digital (ECD), conforme detalhamento contido na Instrução Normativa da RFB no 2.003/2021. A respeito dessa escrituração, é correto afirmar que') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3453999',2104,83,'P1','Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital','CEBRASPE (CESPE) - Ana Tec (SUSEP)/SUSEP/Contabilidade Pública/2025','Caderno Contabilidade Geral Parte 3','Acerca das formalidades essenciais da escrituração, julgue o seguinte item. Ao identificar um erro, ainda que este possa ser corrigido por meio de lançamento de retificação extemporâneo, o contador deve substituir a escrituração contábil em forma digital, mesmo que esta já tenha sido autenticada pelo Sistema Público de Escrituração Digital.','[["Certo","Certo"],["Errado","Errado"]]'::jsonb,'Errado',2025,415,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é Errado."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"Errado — Errado","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Instruções Normativas da RFB sobre Escrituração Contábil Digital"}'::jsonb,'Acerca das formalidades essenciais da escrituração, julgue o seguinte item. Ao identificar um erro, ainda que este possa ser corrigido por meio de lançamento de retificação extemporâneo, o contador deve substituir a escrituração contábil em forma digital, mesmo que esta já ten...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3606385',2105,69,'P2','Contabilidade Geral - Análise das Demonstrações: Conceito, Usuários, Interesses e Tipos de Análise','FURB - FTM (Pref Biguaçu)/Pref Biguaçu/2025','Caderno Contabilidade Geral Parte 3','A análise das demonstrações contábeis permite que, através do cálculo de certos quocientes, o intérprete avalie seus significados comparando desempenhos, tendências e impactos de políticas adotadas. Assinale a alternativa correta:','[["A","Para avaliar o endividamento de uma empresa, não são utilizados os índices de custo de endividamento, alavancagem financeira, relação entre capital de terceiros e capital próprio, entre outros. Para esse fim, os índices mais adequados são o prazo médio de estocagem e o prazo médio de cobrança."],["B","O ciclo de caixa é a quantidade de tempo que a empresa leva para vender e receber um estoque."],["C","Liquidez é a capacidade de pagamento, a curto prazo, das obrigações empresariais. Podem ser calculadas a liquidez corrente, a liquidez imediata, a liquidez seca e a liquidez geral."],["D","O ciclo operacional é o número de dias que a empresa necessita para financiar seu giro, sendo obtido pela subtração do ciclo operacional do prazo de pagamento a fornecedores. É importante para avaliar o capital de giro necessário para as atividades organizacionais."],["E","Os índices que avaliam a rentabilidade da empresa são o prazo médio de estocagem, o prazo médio de pagamento a fornecedores, o prazo médio de cobrança e o ciclo operacional."]]'::jsonb,'C',2025,416,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise das Demonstrações: Conceito, Usuários, Interesses e Tipos de Análise.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é C."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"C — Liquidez é a capacidade de pagamento, a curto prazo, das obrigações empresariais. Podem ser calculadas a liquidez corrente, a liquidez imediata, a liquidez seca e a liquidez geral.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise das Demonstrações: Conceito, Usuários, Interesses e Tipos de Análise"}'::jsonb,'A análise das demonstrações contábeis permite que, através do cálculo de certos quocientes, o intérprete avalie seus significados comparando desempenhos, tendências e impactos de políticas adotadas. Assinale a alternativa correta:') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('4014371',2106,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','Instituto AOCP - Tec (IF CE)/IF CE/Contabilidade/2026','Caderno Contabilidade Geral Parte 3','A análise das demonstrações contábeis é uma ferramenta essencial para avaliar o desempenho econômico-financeiro das entidades. Entre as técnicas mais utilizadas, estão a análise vertical e a análise horizontal. Quanto a esses tipos de análise, assinale a alternativa correta.','[["A","A análise vertical tem como principal objetivo comparar valores de diferentes exercícios sociais, identificando variações percentuais ao longo do tempo."],["B","A análise horizontal consiste em calcular a participação percentual de cada conta em relação a um valor base dentro da mesma demonstração contábil."],["C","A análise vertical permite identificar a evolução histórica das contas patrimoniais e de resultado ao longo de vários períodos."],["D","A análise horizontal avalia a variação absoluta e percentual das contas entre períodos distintos, permitindo identificar tendências de crescimento ou redução."],["E","Tanto a análise vertical quanto a horizontal utilizam valores absolutos, sem aplicação de percentuais."]]'::jsonb,'D',2026,417,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — A análise horizontal avalia a variação absoluta e percentual das contas entre períodos distintos, permitindo identificar tendências de crescimento ou redução.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'A análise das demonstrações contábeis é uma ferramenta essencial para avaliar o desempenho econômico-financeiro das entidades. Entre as técnicas mais utilizadas, estão a análise vertical e a análise horizontal. Quanto a esses tipos de análise, assinale a alternativa correta.') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3961283',2107,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','Legalle - Tec Desen (BADESUL)/BADESUL/Contador/2026','Caderno Contabilidade Geral Parte 3','Considere que o Contador da Agência de Fomento pretende analisar a evolução dos principais grupos do Balanço Patrimonial e das contas da Demonstração do Resultado ao longo de diferentes exercícios, com o objetivo de identificar variações relevantes, avaliar o desempenho histórico da entidade e identificar possíveis tendências para períodos futuros. Para esse fim, o procedimento de análise das demonstrações contábeis MAIS ADEQUADO é a análise:','[["A","Vertical."],["B","Patrimonial."],["C","Setorial."],["D","Horizontal."],["E","Sazonal."]]'::jsonb,'D',2026,418,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é D."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"D — Horizontal.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'Considere que o Contador da Agência de Fomento pretende analisar a evolução dos principais grupos do Balanço Patrimonial e das contas da Demonstração do Resultado ao longo de diferentes exercícios, com o objetivo de identificar variações relevantes, avaliar o desempenho histór...') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
INSERT INTO public.questoes (id,rank,prioridade_base,prioridade_faixa,topic,origin,file_source,stem,options,answer,year,qnum,score,band,resolution,summary) VALUES ('3952143',2108,83,'P1','Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis','FCC - ALegis (ALMS)/ALMS/Controle Interno/2026','Caderno Contabilidade Geral Parte 3','Atenção: Utilize as informações a seguir para responder à questão de número.. O Balanço Patrimonial de uma entidade, que possui ciclo operacional anual, apresentou os seguintes saldos contábeis no final do exercício de 2025: • Caixa: R$ 70.000,00 • Ações em tesouraria: R$ 140.000,00 • Fornecedores: R$ 170.000,00 • Software contábil: R$ 150.000,00 • Aplicações financeiras: R$ 80.000,00 (resgatáveis em 30 dias) • Duplicatas a receber de clientes (vencimento em 20 meses): R$ 100.000,00 • Perdas estimadas com créditos de liquidação duvidosa: R$ 40.000,00 • Empréstimos de longo prazo: R$ 100.000,00 • Estoque: R$ 120.000,00 • Aluguéis dos próximos 8 meses pagos antecipadamente: R$ 38.000,00 • Terrenos destinados à valorização: R$ 150.000,00 • Máquinas e equipamentos de uso: R$ 300.000,00 • Juros a apropriar (12 meses): R$ 55.000,00 • Capital social: R$ 1.000.000,00 • Reserva de lucros: R$ 150.000,00 A conta aluguéis pagos antecipadamente, com base em uma análise vertical, representa','[["A","2,95% do seu grupo patrimonial."],["B","12,34% do seu grupo patrimonial."],["C","5,76% do seu grupo patrimonial."],["D","16,89% do seu grupo patrimonial."],["E","38% do seu grupo patrimonial."]]'::jsonb,'B',2026,419,NULL,NULL,'{"regra":"A resolução deve aplicar o conceito contábil indicado no enunciado e confrontá-lo com cada alternativa, observando reconhecimento, mensuração, classificação e apresentação quando cabíveis.","passos":["Identifique o núcleo do tema: Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis.","Aplique a regra ao caso concreto e elimine as alternativas incompatíveis com o conceito cobrado.","O gabarito registrado é B."],"calculo":"Quando houver valores no enunciado, a conta deve ser montada apenas com os dados fornecidos e conforme a relação conceitual indicada acima.","correta":"B — 12,34% do seu grupo patrimonial.","erradas":["As demais alternativas contrariam a definição, classificação ou consequência contábil aplicável ao caso."],"fundamento":"Contabilidade Geral - Análise Vertical e Horizontal das Demonstrações Contábeis"}'::jsonb,'Atenção: Utilize as informações a seguir para responder à questão de número.. O Balanço Patrimonial de uma entidade, que possui ciclo operacional anual, apresentou os seguintes saldos contábeis no final do exercício de 2025: • Caixa: R$ 70.000,00 • Ações em tesouraria: R$ 140....') ON CONFLICT (id) DO UPDATE SET prioridade_base=EXCLUDED.prioridade_base, prioridade_faixa=EXCLUDED.prioridade_faixa, topic=EXCLUDED.topic, origin=EXCLUDED.origin, file_source=EXCLUDED.file_source, stem=EXCLUDED.stem, options=EXCLUDED.options, answer=EXCLUDED.answer, year=EXCLUDED.year, qnum=EXCLUDED.qnum, score=EXCLUDED.score, band=EXCLUDED.band, resolution=EXCLUDED.resolution, summary=EXCLUDED.summary;
